import { expect, test, uniqueName } from "../../fixtures";

const FUTURE_YEAR = new Date().getFullYear() + 2;
const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = `Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: ${FUTURE_YEAR}-12-31\n`;
const INSURANCE = `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${FUTURE_YEAR}-03-31\n`;

test.describe("review vendors", () => {
  test("approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const vendorRes = await member.post("/api/vendors", {
      data: { name: uniqueName("Approve Co"), category: "logistics", contact_email: "ops@acme.example" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    for (const [kind, text] of [
      ["w9", W9],
      ["insurance_certificate", INSURANCE],
      ["contract", CONTRACT],
    ] as const) {
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
    }

    // Wait for background extraction of all three documents before submitting.
    await expect
      .poll(async () => {
        const docs = await (await member.get(`/api/vendors/${vendor.id}/documents`)).json();
        return docs.map((d: { status: string }) => d.status).sort();
      }, { timeout: 30_000 })
      .toEqual(["extracted", "extracted", "extracted"]);

    const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitRes.status(), await submitRes.text()).toBe(200);

    // Collect the three pending extractions.
    const docs = await (await member.get(`/api/vendors/${vendor.id}/documents`)).json();
    const extractionIds: string[] = [];
    for (const doc of docs as { id: string }[]) {
      const exRes = await member.get(`/api/documents/${doc.id}/extraction`);
      expect(exRes.status(), await exRes.text()).toBe(200);
      const ex = await exRes.json();
      expect(ex.status, await exRes.text()).toBe("pending_review");
      extractionIds.push(ex.id);
    }
    expect(extractionIds).toHaveLength(3);

    // Act: reviewer approves every extraction.
    for (const id of extractionIds) {
      const decision = await reviewer.post(`/api/extractions/${id}/decision`, {
        data: { decision: "approve" },
      });
      expect(decision.status(), await decision.text()).toBe(200);
    }

    // Assert: vendor is approved and the audit event is recorded.
    await expect
      .poll(async () => {
        const res = await member.get(`/api/vendors/${vendor.id}`);
        return (await res.json()).status;
      }, { timeout: 15_000 })
      .toBe("approved");

    await expect
      .poll(async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/audit`);
        const trail = await res.json();
        return trail.items.map((e: { action: string }) => e.action);
      }, { timeout: 15_000 })
      .toContain("vendor.approved");
  });
});
